(function(){
 'use strict';
 const C=window.GuideCore, DB=window.FOREVER_CATALOG, D=window.GUIDE_CONTENT;
 const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const paths={compass:'<circle cx="12" cy="12" r="9"/><path d="m16 8-2 6-6 2 2-6Z"/>',home:'<path d="m3 10 9-7 9 7v10H3Z"/><path d="M9 20v-7h6v7"/>',zap:'<path d="m13 2-9 12h7l-1 8 10-12h-7Z"/>',scroll:'<path d="M6 4h13v14a3 3 0 0 1-3 3H6a3 3 0 0 1-3-3h13v-3M6 18V5a2 2 0 1 0-4 0v3h4m4 0h5m-5 4h5"/>',dungeon:'<path d="M3 21V7l4-4 5 4 5-4 4 4v14Z"/><path d="M9 21v-6a3 3 0 0 1 6 0v6M7 9v2m10-2v2"/>',map:'<path d="m3 6 6-3 6 3 6-3v15l-6 3-6-3-6 3Z"/><path d="M9 3v15m6-12v15"/>',book:'<path d="M12 5C8 2 4 3 2 4v16c4-2 7-1 10 1 3-2 6-3 10-1V4c-4-2-7-1-10 1Zm0 0v16"/>',swords:'<path d="m3 3 14 14m-2 3 5-5m-3 5 3-3M3 3v5h5M21 3 7 17m2 3-5-5m3 5-3-3M21 3v5h-5"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6Z"/><path d="m8 12 3 3 5-6"/>',leaf:'<path d="M20 3c1 9-2 16-9 16-5 0-8-5-5-9 3-5 10-2 14-7ZM4 21l11-11"/>',sprout:'<path d="M12 22V12M12 15C4 15 3 8 3 6c7 0 9 4 9 9Zm0-4c0-6 4-9 9-9 0 5-3 9-9 9"/>',flame:'<path d="M12 2c1 6-5 7-5 11 0 2 2 3 3 1 0-3 2-5 3-5 0 4 5 4 5 9a6 6 0 0 1-12 0c-5-6 2-11 6-16Z"/>',moon:'<path d="M20 15A9 9 0 0 1 9 3a9 9 0 1 0 11 12Z"/>',sparkles:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Zm7-1v4m-2-2h4M3 18v4m-2-2h4"/>',bow:'<path d="M4 4c13-2 18 3 16 16M4 4l16 16M4 4v16h16M2 22 18 6m-5 0h5v5"/>',dagger:'<path d="m20 3-5 12-4-2-2-4Zm-8 9-8 8m-2-2 4 4m2-12 6 6"/>',pickaxe:'<path d="m4 20 12-12M8 3c6-2 11 3 13 9l-5-4-4-1-4-4Z"/>',tent:'<path d="m3 21 9-18 9 18Zm5 0 4-9 4 9M5 4l14 17M19 4 5 21"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',sliders:'<path d="M4 6h4m4 0h8M4 12h9m4 0h3M4 18h2m4 0h10"/><circle cx="10" cy="6" r="2"/><circle cx="15" cy="12" r="2"/><circle cx="8" cy="18" r="2"/>',settings:'<path d="m9 3-1 3-3 1-2 5 2 1 1 4 4 1 2 3 3-2 4-1 1-4 2-2-2-4-3-1-2-3Z"/><circle cx="12" cy="12" r="3"/>',plus:'<path d="M12 5v14M5 12h14"/>',minus:'<path d="M5 12h14"/>',chevron:'<path d="m8 10 4 4 4-4"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',check:'<path d="m5 12 4 4L19 6"/>',gamepad:'<path d="M7 7h10c3 0 5 7 4 11-1 3-5-2-6-3H9c-1 1-5 6-6 3C2 14 4 7 7 7Z"/><path d="M7 9v5m-2-2h5m6-2h.01m2 3h.01"/>',wifi:'<path d="M2 8a16 16 0 0 1 20 0M5 12a11 11 0 0 1 14 0m-10 4a5 5 0 0 1 6 0m-3 4h.01"/>',wifiOff:'<path d="m3 3 18 18M2 8a16 16 0 0 1 8-3m4 0a16 16 0 0 1 8 3M5 12a11 11 0 0 1 7-2m-3 6a5 5 0 0 1 6 0m-3 4h.01"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 16v5h16v-5"/>',external:'<path d="M14 3h7v7m0-7L10 14M10 3H3v18h18v-7"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10h.01"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',edit:'<path d="m14 4 6 6M3 21l5-1L21 7l-6-6L2 14Z"/>',note:'<path d="M4 3h16v18H4Zm4 5h8m-8 4h8m-8 4h5"/>',copy:'<rect x="8" y="8" width="12" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>',mountain:'<path d="m2 21 7-15 4 8 3-5 6 12Zm4-8 3 2 3-3"/>',pin:'<path d="M19 9c0 5-7 12-7 12S5 14 5 9a7 7 0 1 1 14 0Z"/><circle cx="12" cy="9" r="2"/>',heart:'<path d="M20 5c-3-3-7 0-8 2-1-2-5-5-8-2-5 5 8 15 8 15S25 10 20 5Z"/>',warning:'<path d="m12 3 10 18H2Zm0 6v5m0 3h.01"/>'};
 const safeSource=value=>{try{const u=new URL(value);return u.protocol==='https:'&&['www.wowhead.com','wowhead.com'].includes(u.hostname)?u.href:'';}catch{return '';}};
 const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${paths[n]||paths.compass}</svg>`;
 const nav=[['overview','Översikt','compass'],['talents','Talents & builds','zap'],['quests','Quests','scroll'],['dungeons','Dungeons','dungeon'],['zones','Levelingzoner','map'],['abilities','Abilities & träning','sparkles'],['gear','Utrustning','shield'],['professions','Professions','pickaxe'],['notes','Mina anteckningar','note'],['glossary','Nybörjarguiden','book']];
 const categoryNames={quests:'Quests',dungeons:'Dungeons',zones:'Levelingzoner',abilities:'Abilities & träning',gear:'Utrustning',professions:'Professions',tips:'Speltips'};
 const categoryIcons={quests:'scroll',dungeons:'dungeon',zones:'map',abilities:'sparkles',gear:'shield',professions:'pickaxe',tips:'sprout'};
 let state,query='',searchEveryone=false,page=location.hash.slice(1)||'overview',brokenRaw=null,foreignChange=false,toastTimer,registration;
 function builtIn(){const definitions=[[1,'Thundering Strikes',5],[1,'Improved Ghost Wolf',2],[2,'Improved Healing Wave',5],[2,'Totemic Focus',5],[2,'Water Shield',1],[1,'Ancestral Knowledge',5],[1,'Shamanistic Focus',1],[1,'Elemental Weapons',2],[2,'Mindfulness',3],[2,'Healing Focus',1],[1,'Stormstrike',1],[2,'Tidal Mastery',5],[2,'Mana Tide Totem',1],[2,'Healing Way',3],[2,'Nature\'s Swiftness',1],[2,'Purification',5],[2,'Riptide',1],[1,'Toughness',4]];const trees=DB.classes.shaman.trees,order=[],allocations=trees.map(t=>t.talents.map(()=>0));for(const [tree,name,count]of definitions){const index=trees[tree].talents.findIndex(t=>t.name===name);if(index<0)throw Error('Talangen '+name+' saknas i katalogen.');for(let i=0;i<count;i++)order.push({tree,index});allocations[tree][index]=count;}return {id:'wavebreaker-early-wolf-v1',name:'Wavebreaker · tidig Ghost Wolf',classId:'shaman',allocations,order,startLevel:10,url:'https://www.wowhead.com/forever/talent-calc/shaman/v2-0550020210401-5030500115013151',custom:true,source:D.sources.wave};}
 function initialState(){const c=C.createCharacter({name:'Loreia',classId:'shaman',race:'Skyborne',faction:'Horde',level:20,role:'Healer',spec:'Hybrid',professions:['Skinning','Leatherworking','Cooking','First Aid'],demo:true});c.builds=[builtIn()];c.activeBuild=c.builds[0].id;return{schema:1,characters:[c],activeId:c.id,updated:new Date().toISOString()};}
 try{const raw=localStorage.getItem(C.KEY);state=raw?C.normalise(JSON.parse(raw),DB):initialState();}catch(e){try{brokenRaw=localStorage.getItem(C.KEY);}catch{}state=initialState();if(!brokenRaw)brokenRaw='Webbläsaren blockerar lokal lagring.';}
 const character=()=>state.characters.find(c=>c.id===state.activeId)||state.characters[0];
 const klass=()=>DB.classes[character().classId];
 const activeBuild=()=>character().builds.find(b=>b.id===character().activeBuild);
 function notify(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3800);}
 function save(){const el=$('#save-status');try{if(brokenRaw||foreignChange)throw Error('Lagringen behöver kontrolleras.');C.storeState(localStorage,state);el.innerHTML='<i></i> Sparat på enheten';el.classList.remove('error');return true;}catch(e){el.textContent=foreignChange?'Ändrad i annan flik – öppna backup':'Kunde inte spara – öppna backup';el.classList.add('error');return false;}}
 function fillIcons(root=document){root.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));}
 function avatar(c,large=false){const cl=DB.classes[c.classId];return `<span class="class-avatar ${large?'large':''}" style="--class-color:${cl.color}">${icon(cl.icon)}</span>`;}
 function sourceLine(item){const status=item.status==='preliminary'?'Preliminärt':item.status==='editorial'?'Praktiskt tips':'Källuppgift';return `<div class="source-line"><span><i class="status-dot ${item.status==='preliminary'?'preliminary':''}"></i> ${status}${item.updated?' · '+esc(item.updated):''}</span>${safeSource(item.source)?`<a href="${esc(safeSource(item.source))}" target="_blank" rel="noopener noreferrer">Källa ${icon('external')}</a>`:''}</div>`;}
 function levelTag(level,done=false){const l=character().level;return `<span class="level-tag ${level<l&&!done?'overdue':level>l?'future':''}">LV ${level}${level<l&&!done?' · kvar att göra':''}</span>`;}
 function coverage(){return `<div class="coverage-note">${icon('info')}<span>Första utkastet innehåller ett urval quests. ${character().level>30?'Detaljerna efter level 30 utökas löpande. ':''}<button class="term" data-action="about">Se innehållsstatus och källor.</button></span></div>`;}
 function tabs(){const c=character();return `<div class="section-top"><div class="view-tabs" role="group" aria-label="Vilka levels ska visas?">${[['now','Aktuellt nu'],['soon','Kommande'],['all','Allt']].map(([v,t])=>`<button data-view="${v}" class="${c.filters.view===v?'active':''}" aria-pressed="${c.filters.view===v}">${t}</button>`).join('')}</div><label class="form-check small"><input type="checkbox" id="show-done" ${c.filters.showDone?'checked':''}> Visa klara</label></div>`;}
 function inView(item){const c=character(),v=c.filters.view;return v==='all'||(v==='soon'?item.level>c.level&&item.level<=Math.min(60,c.level+10):item.level<=c.level);}
 function visible(item){const c=character();return C.matchesCharacter(item,c)&&(!item.roles||item.roles.includes(c.role))&&c.filters.categories.includes(item.category);}
 function actionableItems(){return [...D.quests,...D.misc].filter(q=>visible(q)&&inView(q)&&(character().filters.showDone||!C.questDone(q,character()))).sort((a,b)=>{const l=character().level;return Number(b.level===l)-Number(a.level===l)||Number(!!b.classId)-Number(!!a.classId)||b.level-a.level;});}
 function questCard(q){const c=character(),done=C.questDone(q,c),partial=q.steps?.filter((_,i)=>c.done[q.id+':'+i]).length||0;return `<article class="quest-card ${done?'done':''}"><div class="quest-head"><input class="quest-check" type="checkbox" data-check="${esc(q.id)}" aria-label="Markera ${esc(q.title)} som klar" ${done?'checked':''}><div class="quest-copy"><div class="card-meta">${levelTag(q.level,done)}<span>${q.classId?esc(DB.classes[q.classId].name)+' · '+(q.category==='quests'?'Klassquest':categoryNames[q.category]||'Guide'):q.kind||categoryNames[q.category]||'Quest'}</span>${partial&&!done?`<span>· ${partial}/${q.steps.length} steg</span>`:''}</div><h3>${esc(q.title)}</h3><p>${esc(q.desc||'Kontrollera och lär den här förmågan när den blir tillgänglig.')}</p></div><span class="quest-icon">${icon(q.classId?'scroll':categoryIcons[q.category]||'check')}</span></div><details class="quest-details"><summary>Visa ${q.steps?.length?'steg och plats':'mer information'}</summary><div class="details-inner">${q.location||q.reward?`<dl>${q.location?`<dt>Start / plats</dt><dd>${esc(q.location)} ${q.coords?coordinate(q.coords):''}</dd>`:''}${q.reward?`<dt>Belöning</dt><dd>${esc(q.reward)}</dd>`:''}</dl>`:''}${q.category==='abilities'?`<p>Träningsnivå enligt Forever-kalkylatorn. Vissa förmågor kräver en klassquest eller annan upplåsning. Kontrollera även din trainer och spellbook.</p><a href="${esc(q.source)}" target="_blank" rel="noopener noreferrer">Läs förmågans beskrivning på Wowhead ${icon('external')}</a>`:''}${q.steps?.length?`<div class="step-list">${q.steps.map((step,i)=>`<label class="step-row ${c.done[q.id+':'+i]?'completed':''}"><input type="checkbox" data-step="${esc(q.id)}" data-index="${i}" ${c.done[q.id+':'+i]?'checked':''}><span>${esc(step)}</span></label>`).join('')}</div>`:''}${sourceLine(q)}</div></details></article>`;}
 function coordinate(coords){return `<button class="coordinate" data-copy="${esc(coords)}" aria-label="Kopiera koordinater">${esc(coords)} ${icon('copy')}</button>`;}
 function availableDungeons(view=true){const c=character();return D.dungeons.filter(d=>visible(d)&&(!view||c.filters.view==='all'||(c.filters.view==='soon'?d.level>c.level&&d.level<=c.level+10:(d.minLevel||d.level)<=c.level&&d.maxLevel>=c.level))).sort((a,b)=>Math.abs((a.level+a.maxLevel)/2-c.level)-Math.abs((b.level+b.maxLevel)/2-c.level));}
 function recommendedZones(){const c=character();return D.zones.filter(z=>visible(z)&&(c.filters.view==='all'||(c.filters.view==='soon'?z.level>c.level&&z.level<=c.level+10:z.level<=c.level&&z.maxLevel>=c.level))).sort((a,b)=>Number(!!b.races)-Number(!!a.races)||Math.abs(a.level+(a.maxLevel-a.level)*.45-c.level)-Math.abs(b.level+(b.maxLevel-b.level)*.45-c.level));}
 function dungeonCard(d,all=false){const c=character(),quests=d.quests.filter(q=>all||C.matchesCharacter(q,c));return `<article class="dungeon-card"><div class="dungeon-banner"><span class="dungeon-symbol">${icon('dungeon')}</span><div><div class="card-meta"><span class="level-tag">REK. ${d.level}–${d.maxLevel}</span><span>${d.short} · ${d.faction==='Both'?'Båda factions':d.faction}</span></div><h3>${esc(d.title)}</h3><small>${esc(d.zone)}</small></div></div><div class="dungeon-stats"><div><span>INTRÄDE ENLIGT DATABAS</span>${d.minLevel?'Level '+d.minLevel:'Behöver bekräftas'}</div><div><span>FÖR DIN LEVEL</span>${c.level<d.level?(d.minLevel&&c.level>=d.minLevel?'Kan gå in · svårare':'Planera inför senare'):c.level<=d.maxLevel?'Inom rekommenderat intervall':'Över rekommenderat intervall'}</div></div><div class="dungeon-quests">${quests.length?quests.map(q=>`<div class="dungeon-quest"><label class="step-row ${c.done[q.id]?'completed':''}"><input type="checkbox" data-check="${q.id}" ${c.done[q.id]?'checked':''}><span>${esc(q.title)} <span class="level-tag">LV ${q.level}${q.levelStatus?' ?':''}</span></span></label><small>${esc(q.location)} ${q.coords?coordinate(q.coords):''}</small>${q.prereq?`<p><strong>Först:</strong> ${esc(q.prereq)}</p>`:''}${q.reward?`<p>Belöning: ${esc(q.reward)}</p>`:''}</div>`).join(''):`<p class="small">${d.quests.length?'Inga quests för din valda karaktär i detta urval.':'Questlistan kompletteras. Öppna källan för mer information.'}</p>`}${d.partial?'<small>Urval av quests · fullständig lista kompletteras.</small>':''}${d.note?`<small>${esc(d.note)}</small>`:''}${sourceLine(d)}${d.entrySource?`<a class="small" href="${esc(d.entrySource)}" target="_blank" rel="noopener noreferrer">Kontrollera inträdesuppgiften ${icon('external')}</a>`:''}</div></article>`;}
 function zoneCard(z){return `<article class="zone-card"><div class="card-meta"><span class="level-tag">LEVEL ${z.level}–${z.maxLevel}</span><span>${z.faction==='Both'?'Båda factions':z.faction}</span></div><span class="zone-icon">${icon('mountain')}</span><h3>${esc(z.title)}</h3><p>${esc(z.desc)}</p><div class="route-hint">${icon('pin')}<span>${esc(z.travel)}</span></div>${sourceLine(z)}</article>`;}
 function empty(title='Här är det lugnt just nu',text='Prova Kommande eller Allt, eller välj fler kategorier.'){return `<div class="empty-state">${icon('compass')}<h3>${title}</h3><p>${text}</p><button class="secondary-button" data-view="all">Visa alla levels</button></div>`;}
 function heading(){const c=character(),n=nav.find(n=>n[0]===page)||nav[0];$('#page-heading').innerHTML=`<div class="heading-top"><span class="tiny-line"></span> ${c.faction.toUpperCase()} · ${esc(DB.classes[c.classId].name.toUpperCase())} · ${esc(c.race.toUpperCase())}</div><div class="heading-row"><div><h1>${page==='overview'?'Äventyret fortsätter.':esc(n[1])}</h1><p class="page-subtitle">${page==='overview'?'Din väg genom Azeroth. Ett steg, en quest, en level i taget.':page==='talents'?'Planera poängen, spara dina builds och följ nästa steg.':page==='notes'?'Din plats för sådant du vill komma ihåg nästa gång.':'Information som följer din karaktär och din level.'}</p></div><button class="draft-badge" data-action="about">UTKAST 0.1</button></div>`;}
 function renderShell(){const c=character();document.body.classList.toggle('compact',c.compact);$('#sidebar-character').innerHTML=`<button class="character-switch" data-action="characters" aria-label="Byt eller hantera karaktär">${avatar(c)}<span class="character-copy"><strong>${esc(c.name)}</strong><small>Level ${c.level} · ${esc(DB.classes[c.classId].name)}</small></span>${icon('chevron')}</button>`;$('#breadcrumb-character').textContent=c.name;$('#navigation').innerHTML=nav.map(([id,name,ic],i)=>`${i===8?'<div class="nav-separator"></div>':''}<button data-page="${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${icon(ic)}${name}</button>`).join('');$('#beginner-toggle').setAttribute('aria-pressed',c.beginner);$('#compact-toggle').setAttribute('aria-pressed',c.compact);$('#filter-count').textContent=c.filters.categories.length;heading();renderContent();}
 function hero(){const c=character();return `<section class="hero" aria-label="Din karaktär och level"><div class="hero-left"><div class="eyebrow">${c.demo?'EXEMPELPROFIL · ANPASSA NÄR DU VILL':'DITT ÄVENTYR I FOREVER'}</div><h2>Hej, ${esc(c.name)}.</h2><p class="hero-description">${c.beginner?'Följ dina nästa steg här nedanför. Bocka av när du är klar — guiden kommer ihåg åt dig.':'Håll kursen, samla dina quests och gör plats för nästa level.'}</p><div class="hero-profile"><span class="faction-dot"></span>${esc(c.faction)}<span>·</span>${esc(c.race)}<span>·</span>${esc(c.spec||DB.classes[c.classId].name)}<button class="text-button" data-action="edit-character">${icon('edit')} Anpassa</button></div></div><div class="hero-right"><label class="level-label" for="character-level">Nuvarande level</label><div class="level-controls"><button class="level-button" data-action="level-down" aria-label="Minska level" ${c.level===1?'disabled':''}>${icon('minus')}</button><div class="level-number"><input id="character-level" class="level-input" type="number" min="1" max="60" inputmode="numeric" value="${c.level}" aria-label="Din nuvarande level"><span>/ 60</span></div><button class="level-button" data-action="level-up" aria-label="Öka level" ${c.level===60?'disabled':''}>${icon('plus')}</button></div><div class="level-progress" role="progressbar" aria-label="Levelresa" aria-valuemin="1" aria-valuemax="60" aria-valuenow="${c.level}"><span style="width:${c.level/60*100}%"></span></div><span class="level-hint">${icon('check')} Level och avbockningar sparas automatiskt</span></div><svg class="hero-decoration" viewBox="0 0 440 240" aria-hidden="true"><path class="light" d="M0 240 95 87l37 43 55-87 65 104 61-59 127 152Z"/><path d="M0 240 112 149l55 41 80-73 76 58 48-27 69 92Z"/><path d="m313 30 22 54h-13l23 50h-17l27 57h-84l26-57h-17l23-50h-12Zm75 65 16 40h-10l17 37h-12l20 42h-61l19-42h-13l17-37h-9Z"/></svg></section>`;}
 function summary(){const c=character(),b=activeBuild(),next=b?C.buildSteps(b,DB).find(s=>s.level>c.level):null,q=D.quests.filter(q=>q.classId&&C.matchesCharacter(q,c)&&!C.questDone(q,c)&&q.level<=c.level+10).sort((a,b)=>Math.abs(a.level-c.level)-Math.abs(b.level-c.level))[0],ds=availableDungeons();return `<div class="summary-grid"><button class="summary-card" data-page="talents"><span class="summary-title">${icon('zap')} Nästa talentpoäng</span><strong>${next?esc(next.name):b?'Planen är genomförd':'Välj din första build'}</strong><small>${next?'Level '+next.level+' · '+next.rank+'/'+next.max:'Öppna talents & builds'}</small></button><button class="summary-card" data-page="quests" ${c.filters.categories.includes('quests')?'':'hidden'}><span class="summary-title">${icon('scroll')} Klassquest</span><strong>${q?esc(q.title):'Alla noterade steg klara'}</strong><small>${q?'Level '+q.level+(q.level<=c.level?' · Tillgänglig enligt källan':' · Snart dags'):'Se hela klassens questlista'}</small></button><button class="summary-card" data-page="dungeons" ${c.filters.categories.includes('dungeons')?'':'hidden'}><span class="summary-title">${icon('dungeon')} Dungeons</span><strong>${ds.length?esc(ds[0].title):'Planera ditt första besök'}</strong><small>${ds.length?ds.length+' i ditt aktuella intervall':'Se kommande dungeons'}</small></button></div>`;}
 function overview(){const c=character(),tasks=actionableItems(),future=[...D.quests].filter(q=>C.matchesCharacter(q,c)&&q.level>c.level&&!C.questDone(q,c)).sort((a,b)=>a.level-b.level).slice(0,3),dungeons=availableDungeons().slice(0,3),zones=recommendedZones().slice(0,2);return hero()+summary()+`<div class="dashboard-grid"><section><div class="section-top"><h2>${icon('scroll')} Att göra nu</h2><button class="text-button" data-page="quests">Alla quests ${icon('arrow')}</button></div>${tabs()}<div class="quest-list">${tasks.length?tasks.slice(0,c.compact?5:6).map(questCard).join(''):empty()}</div>${tasks.length>6?`<button class="text-button" data-page="quests">Se fler uppgifter ${icon('arrow')}</button>`:''}${c.filters.categories.includes('zones')?`<div class="section-top" style="margin-top:28px"><h2>${icon('map')} Här kan du fortsätta</h2><button class="text-button" data-page="zones">Alla zoner ${icon('arrow')}</button></div><div class="card-grid">${zones.length?zones.map(zoneCard).join(''):empty('Välj din nästa zon','Öppna zonerna och välj Kommande eller Allt.')}</div>`:''}</section><aside class="side-stack">${c.filters.categories.includes('dungeons')?`<section class="mini-panel"><div class="panel-heading">${icon('dungeon')}<h3>Dags för en dungeon?</h3></div>${dungeons.length?dungeons.map(d=>`<button class="mini-dungeon" data-dungeon="${d.id}" style="width:100%;text-align:left"><span class="dungeon-symbol">${icon('dungeon')}</span><div><h4>${esc(d.title)}</h4><p>Rek. ${d.level}–${d.maxLevel} · ${d.quests.filter(q=>C.matchesCharacter(q,c)).length} quests i guiden</p></div><span class="mini-arrow">${icon('arrow')}</span></button>`).join(''):'<p class="small">Öppna dungeonlistan för att planera ditt första besök.</p>'}<button class="text-button" data-page="dungeons">Förbered nästa besök ${icon('arrow')}</button></section>`:''}<section class="mini-panel"><div class="panel-heading">${icon('clock')}<h3>På horisonten</h3></div>${future.length?`<ul class="timeline">${future.map(q=>`<li><span class="dot">${q.level}</span><strong>${esc(q.title)}</strong><small>${esc(q.reward||'Nästa klassmilsten')}</small></li>`).join('')}</ul>`:'<p class="small">Nästa klassmilsten fylls på när guiden uppdateras.</p>'}</section>${c.beginner?`<section class="beginner-note"><h3>${icon('sprout')} Ny i Azeroth?</h3><p>Du bestämmer tempot. Välj quests nära din level, besök din <button class="term" data-term="Trainer">trainer</button> och fråga gruppen när något är oklart. Din <button class="term" data-term="Hearthstone">Hearthstone</button> hjälper dig hem igen.</p><button class="text-button" data-page="glossary">Öppna nybörjarguiden ${icon('arrow')}</button></section>`:''}</aside></div>`+coverage();}
 function talents(){const c=character(),b=activeBuild();let html=`<div class="build-toolbar"><select id="active-build" aria-label="Aktiv build">${!c.builds.length?'<option value="">Ingen build sparad</option>':c.builds.map(b=>`<option value="${esc(b.id)}" ${b.id===c.activeBuild?'selected':''}>${esc(b.name)}</option>`).join('')}</select><button class="primary-button" data-action="import-build">${icon('plus')} Importera från Wowhead</button>${c.classId==='shaman'&&!c.builds.some(b=>b.id==='wavebreaker-early-wolf-v1')?'<button class="secondary-button" data-action="add-wavebreaker">Välj Wavebreaker</button>':''}</div>`;
  if(!b)return html+empty('Börja med en build','Skapa en build i Wowheads Forever-kalkylator och klistra in delningslänken här. Guiden läser poängen och ordningen om den finns med.')+`<p style="margin-top:16px"><a href="https://www.wowhead.com/forever/talent-calc/${c.classId}" target="_blank" rel="noopener noreferrer">Öppna kalkylatorn för ${esc(klass().name)} ${icon('external')}</a></p>`;
  const steps=C.buildSteps(b,DB),next=steps.find(s=>s.level>c.level),warnings=C.validateOrder(b,DB),trees=klass().trees;
  html+=`<div class="info-card"><div class="section-top"><h2>${esc(b.name)}</h2><button class="text-button" data-action="edit-build">${icon('edit')} Ändra</button></div><p>${b.custom?'Din anpassade poängordning. Wavebreaker-planen flyttar Improved Ghost Wolf till level 15–16 och behåller Stormstrike till 40.':'Poängfördelningen kommer från din Wowhead-länk. Jämför alltid med den aktuella spelklienten.'}</p><div class="talent-summary">${trees.map((t,i)=>`<div class="tree-total"><strong>${b.allocations[i].reduce((a,b)=>a+b,0)}</strong><small>${esc(t.name)}</small></div>`).join('')}</div><div class="button-row">${b.url?`<a class="secondary-button" href="${esc(b.url)}" target="_blank" rel="noopener noreferrer">Öppna i Wowhead ${icon('external')}</a>`:''}<button class="secondary-button" data-action="edit-order">${icon('edit')} Redigera poängordning</button></div>${sourceLine({source:b.source||b.url||D.sources.wave,updated:DB.updated,status:'sourced'})}</div>`;
  if(warnings.length)html+=`<div class="talent-warning">${icon('warning')}<span>Ordningen behöver ses över: ${esc(warnings[0].message)} ${warnings.length>1?'('+warnings.length+' anmärkningar)':''}</span></div>`;
  if(next)html+=`<div class="talent-feature">${avatar(c,true)}<div><div class="eyebrow">NÄSTA POÄNG · LEVEL ${next.level}</div><h3>${esc(next.name)} <span class="talent-rank">${next.rank}/${next.max}</span></h3><p>${esc(next.treeName)}${next.minLevel>next.level?' · kräver level '+next.minLevel:''}</p></div></div>`;
  if(!steps.length)html+=`<div class="coverage-note">${icon('info')}<span>Länken innehåller slutbuilden men ingen poängordning. Lägg till en ordning för att få instruktioner vid varje level.</span></div>`;
  else{html+=`<div class="section-top" style="margin-top:23px"><h2>Din levelingplan</h2><span class="small">Första poängen: level ${b.startLevel}</span></div><div class="talent-table">${steps.map(s=>`<div class="talent-table-row ${s.level===c.level?'current':s.level>c.level?'future':''}"><span>LV ${s.level}</span><div><a href="https://www.wowhead.com/forever/spell=${s.spell}" target="_blank" rel="noopener noreferrer">${esc(s.name)}</a><span class="talent-rank">${s.rank}/${s.max}</span>${s.level<s.minLevel?`<small style="display:block;color:var(--danger)">Kräver level ${s.minLevel}</small>`:''}</div><span class="talent-tree-label">${esc(s.treeName)}</span></div>`).join('')}</div>`;}
  html+=`<details class="info-card" style="margin-top:20px"><summary>Visa hela slutbuildens poängfördelning</summary><div class="talent-allocation" style="margin-top:15px">${trees.map((t,i)=>`<section><h3>${esc(t.name)}</h3>${t.talents.filter((_,j)=>b.allocations[i][j]).map(tal=>{const j=t.talents.indexOf(tal);return `<div class="allocation-row"><span>${esc(tal.name)}</span><span>${b.allocations[i][j]}/${tal.max}</span></div>`;}).join('')||'<p class="small">Inga poäng.</p>'}</section>`).join('')}</div></details>`;return html;
 }
 function questsPage(){const items=actionableItems().filter(q=>q.category==='quests');return tabs()+`<div class="quest-list">${items.length?items.map(questCard).join(''):empty()}</div>`+coverage();}
 function dungeonsPage(){const ds=availableDungeons();return tabs()+`<div class="coverage-note">${icon('info')}<span>Inträdeslevel är ett tekniskt krav från databasen. Rekommenderad level hjälper dig välja en rimlig utmaning. Gruppens utrustning och erfarenhet spelar också roll.</span></div><div class="card-grid">${ds.length?ds.map(d=>dungeonCard(d)).join(''):empty('Inga dungeons i det valda intervallet')}</div>`+coverage();}
 function zonesPage(){const zs=recommendedZones();return tabs()+`<div class="coverage-note">${icon('map')}<span>Välj en zon där uppdragen passar din level. Zoner kan överlappa; detta är förslag, inte en obligatorisk rutt.</span></div><div class="card-grid">${zs.length?zs.map(zoneCard).join(''):empty()}</div>`+coverage();}
 function abilitiesPage(){const c=character(),abilities=DB.abilities.filter(a=>visible(a)&&inView(a)&&(c.filters.showDone||!c.done[a.id])&&(c.filters.view!=='now'||a.level>=c.level-3)).sort((a,b)=>b.level-a.level);return tabs()+`<div class="coverage-note">${icon('sparkles')}<span>Här visas första träningsnivån för varje förmåga. Högre ranks och träningskostnader kompletteras. Klassquests kan vara ett extra krav.</span></div><div class="quest-list">${abilities.length?abilities.map(questCard).join(''):empty()}</div>`;}
 function gearPage(){const c=character(),examples=D.quests.filter(q=>q.classId&&C.matchesCharacter(q,c)&&q.reward&&/Axe|Hauberk|Fist|Wolfsbane|Wand|Cloak|Ring/.test(q.reward));return `<div class="info-card"><div class="card-meta"><span class="level-tag">${esc(c.role)}</span><span>${esc(klass().name)} · ${esc(c.spec||'Spec ej vald')}</span></div><h2>Välj gear för det du spelar</h2><p style="margin-top:12px">Utgå från din valda specs aktuella klassguide. Vapnets egenskaper, användbara stats och förmågan att överleva behöver vägas ihop under leveling.</p><p>Fullständig statprioritering och dungeonloot för varje spec fylls på. Sparade Wowhead-builds ändrar inte automatiskt dessa råd.</p><a class="secondary-button" href="${esc(D.sources[c.classId])}" target="_blank" rel="noopener noreferrer">Öppna ${esc(klass().name)}-guiden ${icon('external')}</a></div><div class="section-top" style="margin-top:25px"><h2>Vapen och andra klassmål</h2></div><div class="quest-list">${examples.length?examples.map(questCard).join(''):questCard({id:'gear-class-review',category:'gear',level:1,title:'Jämför nästa uppgradering',desc:'Läs klassguidens gearförslag och skriv gärna upp ditt nästa vapen- eller rustningsmål i Mina anteckningar.',source:D.sources[c.classId],updated:DB.updated,status:'editorial'})}</div>`+coverage();}
 function professionsPage(){const c=character(),names=c.professions,items=D.professions.filter(p=>names.includes(p.title));return `<div class="info-card"><div class="section-top"><h2>Dina professions</h2><button class="text-button" data-action="edit-character">${icon('edit')} Välj professions</button></div><p>Välj dina professions i karaktärsprofilen. Här samlas campingrecept och påminnelser för dem.</p><div class="button-row">${names.map(n=>`<span class="level-tag">${esc(n)}</span>`).join('')||'<span class="small">Inga professions valda ännu.</span>'}</div></div><div class="card-grid" style="margin-top:18px">${items.map(p=>`<article class="info-card"><div class="card-meta"><span class="level-tag">${esc(p.title)}</span></div><h3>${esc(p.item)}</h3><p>${esc(p.desc)}</p><label class="form-check"><input type="checkbox" data-check="${p.id}" ${c.done[p.id]?'checked':''}> Recept / upplåsning kontrollerad</label>${sourceLine(p)}</article>`).join('')}</div><div style="margin-top:20px">${questCard(D.quests.find(q=>q.id==='camp-outdoors'))}</div>`;}
 function glossaryPage(){return `<div class="beginner-note" style="margin-bottom:20px"><h3>${icon('sprout')} Börja enkelt</h3><p>Prata med figurer som har uppdrag, läs din questlogg och prova förmågorna i lugn takt. Välj din karaktärs riktiga level med + och −. Bocka av sådant du gjort. Inför en dungeon: bestäm roller och hämta uppdragen tillsammans.</p></div><div class="glossary-grid">${D.glossary.map(t=>`<article class="glossary-term"><h3>${esc(t.title)}</h3><p>${esc(t.desc)}</p></article>`).join('')}</div>`;}
 function searchPage(){const c=character(),needle=query.toLocaleLowerCase('sv').trim(),tokens=needle.split(/\s+/);const talents=Object.entries(DB.classes).flatMap(([classId,cl])=>cl.trees.flatMap(t=>t.talents.map(tal=>({id:'talent-'+tal.id,category:'talents',classId,title:tal.name,desc:t.name,source:'https://www.wowhead.com/forever/spell='+tal.spell,level:1,status:'sourced'}))));const all=[...D.quests,...D.misc,...D.dungeons,...D.zones,...DB.abilities,...D.professions,...D.glossary,...talents];const results=all.filter(item=>(searchEveryone||C.matchesCharacter(item,c))&&tokens.every(t=>JSON.stringify([item.title,item.desc,item.steps,item.quests,item.location,item.reward,item.item]).toLocaleLowerCase('sv').includes(t)));return `<div class="section-top"><h2>${results.length} träff${results.length===1?'':'ar'} för ”${esc(query)}”</h2><button class="text-button" data-action="clear-search">Rensa sökning ${icon('close')}</button></div><div class="quest-list">${results.length?results.slice(0,100).map(item=>item.category==='dungeons'?dungeonCard(item,searchEveryone):item.category==='zones'?zoneCard(item):item.category==='glossary'?`<article class="glossary-term"><h3>${esc(item.title)}</h3><p>${esc(item.desc)}</p></article>`:item.category==='talents'?`<article class="info-card"><div class="card-meta">TALANG · ${esc(DB.classes[item.classId].name)} · ${esc(item.desc)}</div><h3>${esc(item.title)}</h3>${sourceLine(item)}</article>`:questCard(item)).join(''):empty('Ingen träff ännu','Prova ett engelskt spelnamn eller sök i alla klasser och factions.')}</div>`;}
 function renderContent(){const c=character();$('#search-options').hidden=!query;let html;if(query)html=searchPage();else if(page==='overview')html=overview();else if(C.CATEGORIES.includes(page)&&!c.filters.categories.includes(page))html=`<div class="empty-state">${icon('sliders')}<h3>Kategorin är dold</h3><p>Du har dolt ${categoryNames[page].toLowerCase()} för den här karaktären.</p><button class="secondary-button" data-action="filters">Ändra kategorier</button></div>`;else if(page==='talents')html=talents();else if(page==='quests')html=questsPage();else if(page==='dungeons')html=dungeonsPage();else if(page==='zones')html=zonesPage();else if(page==='abilities')html=abilitiesPage();else if(page==='gear')html=gearPage();else if(page==='professions')html=professionsPage();else if(page==='glossary')html=glossaryPage();else if(page==='notes')html=`<section class="info-card"><h2>Till nästa gång</h2><p style="margin-top:10px">Skriv ned nästa quest, var du parkerade karaktären eller vad du vill göra med gruppen.</p><label class="form-field"><span>Anteckningar för ${esc(c.name)}</span><textarea id="character-notes" class="notes-area" placeholder="Nästa gång ska jag…">${esc(c.notes)}</textarea></label><span class="note-footer">Sparas automatiskt för den här karaktären.</span></section>`;else{page='overview';html=overview();}$('#content').innerHTML=html;}
 function go(id){page=nav.some(n=>n[0]===id)?id:'overview';query='';$('#search').value='';history.replaceState(null,'','#'+page);closeMenu();renderShell();window.scrollTo({top:0,behavior:'instant'});}
 function closeMenu(){$('#sidebar').classList.remove('open');$('#menu-backdrop').hidden=true;}
 function dialog(title,body,footer=''){const el=$('#dialog');$('#dialog-content').innerHTML=`<div class="dialog-top"><h2>${title}</h2><button class="icon-button" data-action="close-dialog" aria-label="Stäng dialog">${icon('close')}</button></div><div class="dialog-body">${body}</div>${footer?`<div class="dialog-footer">${footer}</div>`:''}`;if(!el.open)el.showModal();}
 function charactersDialog(){dialog('Dina karaktärer',`<p>Välj vem som fortsätter äventyret. Varje karaktär har egna framsteg och inställningar.</p><div class="character-list">${state.characters.map(c=>`<button class="character-option ${c.id===state.activeId?'active':''}" data-character="${c.id}">${avatar(c)}<div><strong>${esc(c.name)}${c.demo?' · Exempel':''}</strong><small>Level ${c.level} · ${esc(c.race)} ${DB.classes[c.classId].name} · ${c.faction}</small></div>${c.id===state.activeId?icon('check'):icon('arrow')}</button>`).join('')}</div><div class="character-actions"><button class="primary-button" data-action="new-character">${icon('plus')} Ny karaktär</button><button class="secondary-button" data-action="edit-character">${icon('edit')} Redigera vald</button></div>`);}
 function characterForm(edit=false){const c=edit?character():C.createCharacter({race:'',classId:'warrior',faction:'Horde'});dialog(edit?'Din karaktär':'Ett nytt äventyr',`<form id="character-form" data-edit="${edit}"><div class="form-grid"><label class="form-field wide"><span>Karaktärens namn</span><input name="name" value="${edit?esc(c.name):''}" maxlength="50" placeholder="Vad heter din karaktär?" required autocomplete="off"></label><label class="form-field"><span>Klass</span><select name="classId" aria-label="Klass" ${edit?'disabled':''}>${Object.entries(DB.classes).map(([id,cl])=>`<option value="${id}" ${c.classId===id?'selected':''}>${cl.name}</option>`).join('')}</select>${edit?'<span class="field-hint">Skapa en ny profil för en annan klass.</span>':''}</label><label class="form-field"><span>Faction</span><select name="faction" aria-label="Faction"><option ${c.faction==='Horde'?'selected':''}>Horde</option><option ${c.faction==='Alliance'?'selected':''}>Alliance</option></select></label><label class="form-field"><span>Ras</span><select name="race" aria-label="Ras">${['Human','Dwarf','Night Elf','Gnome','Orc','Undead','Tauren','Troll','Skyborne'].map(r=>`<option ${c.race===r?'selected':''}>${r}</option>`).join('')}</select><span class="field-hint">Välj samma ras och faction som i spelet.</span></label><label class="form-field"><span>Nuvarande level</span><input type="number" min="1" max="60" name="level" value="${c.level}" required></label><label class="form-field"><span>Roll</span><select name="role" aria-label="Roll">${['DPS','Healer','Tank'].map(r=>`<option ${c.role===r?'selected':''}>${r}</option>`).join('')}</select></label><label class="form-field"><span>Spec / inriktning</span><input name="spec" value="${esc(c.spec)}" placeholder="Till exempel Hybrid" maxlength="40"></label></div><h3>Professions</h3><div class="form-grid">${D.professions.map(p=>`<label class="form-check"><input type="checkbox" name="professions" value="${p.title}" ${c.professions.includes(p.title)?'checked':''}> ${p.title}</label>`).join('')}</div><p class="field-hint" style="margin-top:12px">Välj dina två huvudsakliga professions och de sekundära du använder.</p><div id="form-error" class="error-text" hidden></div><button type="submit" hidden></button></form>`,`<button class="secondary-button" data-action="close-dialog">Avbryt</button><button class="primary-button" type="submit" form="character-form">${edit?'Spara karaktär':'Skapa karaktär'}</button>`);}
 function filterDialog(){const c=character();dialog('Välj vad du vill se',`<p>Inställningarna gäller ${esc(c.name)}. Sökfunktionen hittar även innehåll i dolda kategorier.</p><div class="filter-options">${C.CATEGORIES.map(cat=>`<label class="filter-option">${icon(categoryIcons[cat])}<span>${categoryNames[cat]}</span><input type="checkbox" data-category="${cat}" ${c.filters.categories.includes(cat)?'checked':''}></label>`).join('')}</div>`,`<button class="secondary-button" data-action="all-categories">Visa alla kategorier</button><button class="primary-button" data-action="close-dialog">Klart</button>`);}
 function settings(){dialog('Inställningar & backup',`<div class="settings-row"><span><strong>Automatisk sparning</strong><small>${brokenRaw?'Lagringen behöver ses över. Exportera säkerhetskopian nedan.':foreignChange?'En annan flik har ändrat datan. Exportera ditt arbete och ladda sedan om.':'Aktiv i den här webbläsaren för alla karaktärer.'}</small></span>${icon(brokenRaw||foreignChange?'warning':'check')}</div><div class="settings-row"><span><strong>Offlineläge</strong><small>${location.protocol==='file:'?'Öppna den publicerade sidan för att aktivera offlinecache.':navigator.serviceWorker?.controller?'Guidens lokala filer är tillgängliga offline.':'Aktiveras när sidan har laddats via HTTPS.'}</small></span>${icon('wifi')}</div><div class="backup-notice">Profilerna finns i denna webbläsare. Exportera en backup om du ska byta enhet eller rensa webbplatsdata.</div><h3>Exportera och importera</h3><div class="button-row"><button class="primary-button" data-action="export">${icon('download')} Alla karaktärer</button><button class="secondary-button" data-action="export-character">${icon('download')} Bara ${esc(character().name)}</button><button class="secondary-button" data-action="import-backup">${icon('upload')} Importera backup</button>${brokenRaw?'<button class="danger-button" data-action="export-raw">Spara tidigare rådata</button>':''}</div><p class="field-hint" style="margin-top:12px">Importerade karaktärer läggs till som nya profiler. Dina befintliga profiler behålls.</p><h3>Vald karaktär</h3><div class="button-row"><button class="secondary-button" data-action="edit-character">${icon('edit')} Redigera ${esc(character().name)}</button><button class="danger-button" data-action="delete-character" ${state.characters.length<=1?'disabled':''}>Ta bort karaktär</button></div>${brokenRaw?'<div class="backup-notice">Tidigare data har skyddats från överskrivning. Exportera den först. Du kan sedan välja att starta om den lokala sparningen.</div><button class="danger-button" data-action="reset-broken">Starta om lokal sparning</button>':''}`);}
 function about(){dialog('Om guiden & källor',`<p>${esc(D.notes)}</p><div class="backup-notice">Funktionerna fungerar för alla nio klasser. Innehållet är ett första urval. Klassquests kan ha flera rasvarianter; exakta NPC:er och belöningar kompletteras där de saknas.</div><h3>Vad betyder statusen?</h3><p><strong>Källuppgift:</strong> hittad i aktuell Forever-källa, inte självtestad i spelet.<br><strong>Preliminärt:</strong> behöver mer kontroll eller bättre underlag.<br><strong>Praktiskt tips:</strong> redaktionellt råd.</p><h3>Huvudkällor</h3><ul class="sources-list"><li><a href="https://www.wowhead.com/forever/talent-calc" target="_blank" rel="noopener noreferrer">Wowheads Forever-kalkylator</a><small>Talangnamn, ranktak, förkrav, poänglänkar och första träningsnivåer. Dataversion v2, hämtad ${DB.updated}.</small></li><li><a href="${D.sources.wave}" target="_blank" rel="noopener noreferrer">Wavebreaker Shaman Hybrid</a><small>Utgångspunkt för den modifierade Shaman-planen. Talangnamn följer aktuella kalkylatordata.</small></li><li><a href="${D.sources.dungeons}" target="_blank" rel="noopener noreferrer">Forever dungeonöversikt</a><small>Rekommenderade intervall. Separata dungeonkällor finns i korten.</small></li><li><a href="${D.sources.camp}" target="_blank" rel="noopener noreferrer">Forever Camping</a></li><li><a href="${D.sources.zones}" target="_blank" rel="noopener noreferrer">Forever-zondatabasen</a><small>Levelintervall och inträdesuppgifter. Nollvärden tolkas som okänt krav.</small></li></ul><h3>Senaste ändringar</h3><div class="changelog">${D.changelog.map(x=>`<strong>${esc(x.version)} · ${x.date}</strong><p>${esc(x.text)}</p>`).join('')}</div><p class="small">Inofficiellt hjälpmedel. World of Warcraft tillhör Blizzard Entertainment. Guidens egna profiluppgifter skickas inte till en server.</p>`);}
 let pendingBuild=null;
 function importBuild(){pendingBuild=null;dialog('Importera från Wowhead',`<p>Öppna kalkylatorn för Forever, välj dina talents och klistra in hela delningslänken. En sparad poängordning importeras också.</p><form id="build-import-form"><label class="form-field"><span>Buildens namn</span><input name="name" maxlength="80" placeholder="Till exempel Solo eller Resto"></label><label class="form-field" style="margin-top:13px"><span>Wowhead-länk</span><input name="url" type="url" required placeholder="https://www.wowhead.com/forever/talent-calc/…"></label><div id="build-import-error" class="error-text" hidden></div><div id="build-import-preview"></div></form><p style="margin-top:15px"><a class="small" href="https://www.wowhead.com/forever/talent-calc/${character().classId}" target="_blank" rel="noopener noreferrer">Öppna ${esc(klass().name)}-kalkylatorn ${icon('external')}</a></p>`,`<button class="secondary-button" data-action="close-dialog">Avbryt</button><button class="primary-button" type="submit" form="build-import-form">Läs in och granska</button><button class="primary-button" data-action="save-build" id="save-build" hidden>Spara build</button>`);}
 function editOrder(){const b=activeBuild();if(!b)return;const text=b.order.map(s=>`${s.tree+1}:${s.index+1}`).join('\n');dialog('Redigera poängordning',`<p>Varje rad är en talentpoäng. Skriv <strong>träd:talang</strong>, till exempel <strong>2:2</strong>. Båda numren börjar på 1. Ordningen måste innehålla exakt de poäng som finns i din slutbuild.</p><form id="order-form"><label class="form-field"><span>Första talentpoängen vid level</span><input name="startLevel" type="number" min="5" max="10" value="${b.startLevel}" required></label><p class="field-hint">Standard är level 10. Justera om din karaktär har tidigare talentpoäng via Legacy.</p><label class="form-field"><span>Poängordning</span><textarea name="order" class="manual-order" spellcheck="false">${esc(text)}</textarea></label><div class="error-text" id="order-error" hidden></div><details style="margin-top:15px"><summary class="small">Visa talangnummer</summary>${klass().trees.map((t,i)=>`<h3>${i+1}. ${esc(t.name)}</h3><div class="small">${t.talents.map((t,j)=>`${i+1}:${j+1} — ${esc(t.name)} (${b.allocations[i][j]} poäng i builden)`).join('<br>')}</div>`).join('')}</details></form>`,`<button class="secondary-button" data-action="close-dialog">Avbryt</button><button class="primary-button" type="submit" form="order-form">Spara ordning</button>`);}
 function download(filename,text){const blob=new Blob([text],{type:'application/json;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 function exportBackup(single=false){const data=single?{...state,characters:[character()],activeId:character().id}:state;download('fardvag-'+(single?character().name.replace(/[^a-zA-Z0-9-]/g,'-'):'backup')+'-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(data,null,2));notify('Backup exporterad.');}
 function changeLevel(value){const c=character();c.level=C.clamp(value,1,60);save();renderShell();}
 document.addEventListener('click',async e=>{
  const target=e.target.closest('button,[data-page]');if(!target)return;
  if(target.dataset.page){go(target.dataset.page);return;}
  if(target.dataset.view){character().filters.view=target.dataset.view;save();renderContent();return;}
  if(target.dataset.character){state.activeId=target.dataset.character;save();$('#dialog').close();renderShell();notify('Fortsätter med '+character().name);return;}
  if(target.dataset.term){const t=D.glossary.find(t=>t.title===target.dataset.term);if(t)dialog(esc(t.title),`<p>${esc(t.desc)}</p>`);return;}
  if(target.dataset.dungeon){const d=D.dungeons.find(d=>d.id===target.dataset.dungeon);if(d)dialog(esc(d.title),dungeonCard(d));return;}
  if(target.dataset.copy){try{await navigator.clipboard.writeText(target.dataset.copy);notify('Koordinater kopierade.');}catch{dialog('Koordinater',`<label class="form-field"><span>Kopiera raden</span><input readonly value="${esc(target.dataset.copy)}"></label>`);}return;}
  const a=target.dataset.action,c=character();
  if(a==='level-up')changeLevel(c.level+1);else if(a==='level-down')changeLevel(c.level-1);else if(a==='menu'){$('#sidebar').classList.toggle('open');$('#menu-backdrop').hidden=!$('#sidebar').classList.contains('open');}
  else if(a==='beginner'){c.beginner=!c.beginner;save();renderShell();notify(c.beginner?'Nybörjarläge på.':'Nybörjarläge av.');}
  else if(a==='compact'){c.compact=!c.compact;save();renderShell();notify(c.compact?'Kompakt spelläge på.':'Vanligt läge på.');}
  else if(a==='characters')charactersDialog();else if(a==='new-character')characterForm(false);else if(a==='edit-character')characterForm(true);else if(a==='close-dialog')$('#dialog').close();else if(a==='filters')filterDialog();else if(a==='all-categories'){c.filters.categories=[...C.CATEGORIES];save();renderShell();filterDialog();}
  else if(a==='settings')settings();else if(a==='about')about();else if(a==='import-build')importBuild();else if(a==='save-build'&&pendingBuild){c.builds.push(pendingBuild);c.activeBuild=pendingBuild.id;pendingBuild=null;save();$('#dialog').close();go('talents');notify('Build och eventuell poängordning sparad.');}
  else if(a==='add-wavebreaker'){const b=builtIn();c.builds.push(b);c.activeBuild=b.id;save();renderContent();}
  else if(a==='edit-order')editOrder();else if(a==='edit-build'){const b=activeBuild();dialog('Redigera build',`<form id="build-edit-form"><label class="form-field"><span>Namn</span><input name="name" maxlength="80" value="${esc(b.name)}" required></label></form><button class="danger-button" style="margin-top:20px" data-action="delete-build">Ta bort denna build</button>`,`<button class="secondary-button" data-action="close-dialog">Avbryt</button><button class="primary-button" type="submit" form="build-edit-form">Spara</button>`);}
  else if(a==='delete-build'){const id=c.activeBuild;c.builds=c.builds.filter(b=>b.id!==id);c.activeBuild=c.builds[0]?.id||null;save();$('#dialog').close();renderContent();}
  else if(a==='export')exportBackup();else if(a==='export-character')exportBackup(true);else if(a==='import-backup')$('#backup-file').click();else if(a==='export-raw')download('fardvag-tidigare-radata.json',brokenRaw||'');
  else if(a==='reset-broken')dialog('Starta om lokal sparning?',`<p>Spara din tidigare rådata först. När du fortsätter ersätts den tidigare sparfilen av de profiler som nu visas.</p>`,`<button class="secondary-button" data-action="close-dialog">Avbryt</button><button class="danger-button" data-action="confirm-reset">Starta om sparningen</button>`);
  else if(a==='confirm-reset'){brokenRaw=null;foreignChange=false;save();$('#dialog').close();notify('Lokal sparning omstartad.');}
  else if(a==='delete-character'&&state.characters.length>1)dialog('Ta bort '+esc(c.name)+'?',`<p>Karaktärens lokala framsteg tas bort. Du kan exportera en backup först från inställningarna.</p>`,`<button class="secondary-button" data-action="close-dialog">Avbryt</button><button class="danger-button" data-action="confirm-delete">Ta bort karaktären</button>`);
  else if(a==='confirm-delete'&&state.characters.length>1){state.characters=state.characters.filter(x=>x.id!==c.id);state.activeId=state.characters[0].id;save();$('#dialog').close();renderShell();}
  else if(a==='clear-search'){query='';$('#search').value='';renderContent();$('#search').focus();}
  else if(a==='update-app')location.reload();
 });
 const byId=new Map([...D.quests,...D.misc,...DB.abilities,...D.professions,...D.dungeons.flatMap(d=>d.quests)].map(q=>[q.id,q]));
 document.addEventListener('change',e=>{const el=e.target,c=character();
  if(el.id==='character-level'){changeLevel(el.value);return;}
  if(el.dataset.check){const item=byId.get(el.dataset.check)||{id:el.dataset.check};C.setDone(c,item,el.checked);save();const insideDialog=el.closest('dialog');if(insideDialog){const d=D.dungeons.find(d=>d.quests.some(q=>q.id===item.id));if(d)dialog(esc(d.title),dungeonCard(d));}renderContent();return;}
  if(el.dataset.step){const item=byId.get(el.dataset.step),key=item.id+':'+el.dataset.index;if(el.checked)c.done[key]=true;else delete c.done[key];if(item.steps.every((_,i)=>c.done[item.id+':'+i]))c.done[item.id]=true;else delete c.done[item.id];save();const details=el.closest('details');if(details){const label=el.closest('label');label.classList.toggle('completed',el.checked);const parent=details.closest('.quest-card');const checkbox=parent?.querySelector('[data-check]');if(checkbox)checkbox.checked=C.questDone(item,c);}return;}
  if(el.dataset.category){c.filters.categories=el.checked?[...new Set([...c.filters.categories,el.dataset.category])]:c.filters.categories.filter(x=>x!==el.dataset.category);save();$('#filter-count').textContent=c.filters.categories.length;renderContent();return;}
  if(el.id==='active-build'){c.activeBuild=el.value;save();renderContent();return;}
  if(el.id==='show-done'){c.filters.showDone=el.checked;save();renderContent();return;}
  if(el.id==='search-everyone'){searchEveryone=el.checked;renderContent();return;}
 });
 document.addEventListener('input',e=>{if(e.target.closest('#build-import-form')){pendingBuild=null;$('#save-build').hidden=true;$('#build-import-preview').innerHTML='';}if(e.target.id==='character-notes'){character().notes=e.target.value.slice(0,20000);save();}});
 $('#search').addEventListener('input',e=>{query=e.target.value.slice(0,150);renderContent();});
 document.addEventListener('submit',e=>{
  if(e.target.id==='character-form'){e.preventDefault();const form=e.target,f=new FormData(form),edit=form.dataset.edit==='true',prof=f.getAll('professions'),primary=prof.filter(n=>!['Cooking','First Aid','Fishing'].includes(n));if(primary.length>2){$('#form-error').hidden=false;$('#form-error').textContent='Välj högst två huvudsakliga professions.';return;}const values={name:f.get('name').trim(),classId:edit?character().classId:f.get('classId'),race:f.get('race'),faction:f.get('faction'),level:+f.get('level'),role:f.get('role'),spec:f.get('spec'),professions:prof};if(!values.name)return;if(edit){Object.assign(character(),values,{demo:false});}else{if(state.characters.length>=100){notify('Du har nått gränsen på 100 profiler.');return;}const c=C.createCharacter(values);if(c.classId==='shaman'){c.builds=[builtIn()];c.activeBuild=c.builds[0].id;}state.characters.push(c);state.activeId=c.id;}save();$('#dialog').close();go('overview');notify(edit?'Karaktären är uppdaterad.':'Ditt nya äventyr är sparat.');}
  else if(e.target.id==='build-import-form'){e.preventDefault();const f=new FormData(e.target),error=$('#build-import-error');try{pendingBuild=C.parseWowhead(f.get('url'),DB,character().classId);if(f.get('name').trim())pendingBuild.name=f.get('name').trim();const totals=pendingBuild.allocations.map(t=>t.reduce((a,b)=>a+b,0)),warn=C.validateOrder(pendingBuild,DB);$('#build-import-preview').innerHTML=`<div class="import-preview"><strong>${esc(pendingBuild.name)}</strong><p>${totals.join(' / ')} poäng · ${pendingBuild.order.length?'Sparad ordning med '+pendingBuild.order.length+' poäng':'Ingen poängordning i länken'}</p><p>Första poängen: level ${pendingBuild.startLevel}</p>${warn.length?`<p style="color:var(--danger);margin-top:8px">Ordningen behöver justeras: ${esc(warn[0].message)}</p>`:''}</div>`;error.hidden=true;$('#save-build').hidden=false;}catch(err){pendingBuild=null;error.hidden=false;error.textContent=err.message;$('#build-import-preview').innerHTML='';$('#save-build').hidden=true;}}
  else if(e.target.id==='order-form'){e.preventDefault();const b=activeBuild(),f=new FormData(e.target),lines=f.get('order').trim().split(/\s+/).filter(Boolean),counts=klass().trees.map(t=>t.talents.map(()=>0));try{const order=lines.map(line=>{const m=line.match(/^([1-3]):([1-9]\d?)$/);if(!m)throw Error('Varje rad måste ha formatet träd:talang.');const tree=+m[1]-1,index=+m[2]-1;if(!klass().trees[tree].talents[index])throw Error('Ett talangnummer finns inte.');counts[tree][index]++;return{tree,index};});if(JSON.stringify(counts)!==JSON.stringify(b.allocations))throw Error('Ordningen måste innehålla exakt slutbuildens poängfördelning.');const next={...b,order,startLevel:C.clamp(f.get('startLevel'),5,10)},warn=C.validateOrder(next,DB);if(warn.length)throw Error('Poäng '+warn[0].point+': '+warn[0].message);Object.assign(b,next);save();$('#dialog').close();renderContent();notify('Poängordningen är sparad.');}catch(err){$('#order-error').hidden=false;$('#order-error').textContent=err.message;}}
  else if(e.target.id==='build-edit-form'){e.preventDefault();activeBuild().name=new FormData(e.target).get('name').trim().slice(0,80)||'Min build';save();$('#dialog').close();renderContent();}
 });
 $('#backup-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5*1024*1024)throw Error('Backupfilen får vara högst 5 MB.');const imported=C.normalise(JSON.parse(await file.text()),DB);if(imported.characters.length+state.characters.length>100)throw Error('Importen skulle ge fler än 100 profiler.');for(const c of imported.characters)c.id=C.uuid();state.characters.push(...imported.characters);state.activeId=imported.characters[0].id;save();$('#dialog').close();renderShell();notify(imported.characters.length+' karaktärsprofil(er) importerade.');}catch(err){notify('Import misslyckades: '+err.message);}finally{e.target.value='';}});
 $('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=$('#dialog').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#dialog').close();}});
 $('#menu-backdrop').addEventListener('click',closeMenu);
 document.addEventListener('keydown',e=>{if(e.key==='/'&&!$('#dialog').open&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();$('#search').focus();}if(e.key==='Escape')closeMenu();});
 window.addEventListener('hashchange',()=>{page=location.hash.slice(1)||'overview';renderShell();});
 window.addEventListener('storage',e=>{if(e.key===C.KEY&&e.newValue!==e.oldValue){foreignChange=true;$('#save-status').classList.add('error');$('#save-status').textContent='Ändrad i annan flik – öppna backup';notify('Guiden ändrades i en annan flik. Exportera eventuellt arbete och ladda om.');}});
 function offlineStatus(){const status=$('#offline-status');if(window.FARDVAG_STANDALONE){status.innerHTML=icon('check')+' Fristående fil';return;}if(!navigator.onLine)status.innerHTML=icon('wifiOff')+' Offlineläge';else if(navigator.serviceWorker?.controller)status.innerHTML=icon('check')+' Redo att användas offline';else status.innerHTML=icon('wifi')+(location.protocol==='file:'||!window.isSecureContext?' Offlineläge aktiveras på HTTPS':' Förbereder offlineläge');}
 window.addEventListener('online',offlineStatus);window.addEventListener('offline',offlineStatus);
 if(!window.FARDVAG_STANDALONE&&'serviceWorker'in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./sw.js',{scope:'./'}).then(r=>{registration=r;return navigator.serviceWorker.ready;}).then(()=>{offlineStatus();navigator.serviceWorker.addEventListener('controllerchange',offlineStatus);registration.addEventListener('updatefound',()=>{const worker=registration.installing;worker?.addEventListener('statechange',()=>{if(worker.state==='installed'&&navigator.serviceWorker.controller){$('#offline-status').innerHTML=icon('download')+' Ny version finns · <button data-action="update-app">Ladda om</button>';}});});}).catch(()=>{$('#offline-status').innerHTML=icon('info')+' Offlinecache kunde inte aktiveras';});
 fillIcons();renderShell();offlineStatus();if(brokenRaw)notify('Sparningen behöver kontrolleras. Öppna Inställningar & backup.');else save();
})();
